/**
 * Hosted UI /login redirect web ACL (amfa-458).
 *
 * The admin-portal stack owns one regional WAF web ACL that turns Cognito's
 * `/login` CSRF-fallback page into a 302 to the AMFA sign-in retry page. Every
 * tenant user pool must be associated with it. The ACL ARN arrives through
 * LOGIN_REDIRECT_WEB_ACL_ARN; a pool is associated right after creation and
 * disassociated before rollback deletes it.
 */
import {
  WAFV2Client,
  AssociateWebACLCommand,
  DisassociateWebACLCommand,
} from "@aws-sdk/client-wafv2";

const WEB_ACL_ARN_ENV = "LOGIN_REDIRECT_WEB_ACL_ARN";

let defaultClient;
function getClient() {
  defaultClient ??= new WAFV2Client({ region: process.env.AWS_REGION });
  return defaultClient;
}

function webAclArn() {
  return process.env[WEB_ACL_ARN_ENV] || "";
}

/**
 * Associate the tenant user pool with the shared /login redirect web ACL.
 * Throws when the ACL ARN is not configured: provisioning a pool that keeps
 * the dead-end /login page is a deployment misconfiguration, not a tenant
 * condition, so it must fail loudly rather than silently ship without it.
 */
export async function attachLoginRedirectWebAcl(
  userPoolArn,
  { client = getClient(), logger = console } = {},
) {
  const arn = webAclArn();
  if (!arn) {
    throw new Error(`${WEB_ACL_ARN_ENV} is not configured`);
  }
  await client.send(
    new AssociateWebACLCommand({ WebACLArn: arn, ResourceArn: userPoolArn }),
  );
  logger.info(`[WAF] Associated ${userPoolArn} with /login redirect web ACL`);
}

/**
 * Remove the association before the pool is deleted. Already-absent
 * associations and a missing ACL configuration are not errors here; anything
 * else propagates so the caller decides whether it blocks rollback.
 */
export async function detachLoginRedirectWebAcl(
  userPoolArn,
  { client = getClient(), logger = console } = {},
) {
  if (!userPoolArn) return;
  if (!webAclArn()) {
    logger.warn(`[WAF] ${WEB_ACL_ARN_ENV} not configured, skipping disassociation`);
    return;
  }
  try {
    await client.send(new DisassociateWebACLCommand({ ResourceArn: userPoolArn }));
    logger.info(`[WAF] Disassociated ${userPoolArn} from /login redirect web ACL`);
  } catch (error) {
    if (error.name === "WAFNonexistentItemException") {
      logger.info(`[WAF] ${userPoolArn} had no web ACL association`);
      return;
    }
    throw error;
  }
}
